mapper.update:
update cart_items set quantity=quantity+#{quantity},price=#{price},
  item_remark=case when #{remark} is not null and trim(#{remark})<>'' then #{remark} else item_remark end
where id=#{itemId}

update carts set user_id=null,meal_slot_id=null,service_date=null,
  expected_meal_time=case
    when date(expected_meal_time)=current_date and expected_meal_time>now()
      and minute(expected_meal_time) mod 15=0 and second(expected_meal_time)=0
    then expected_meal_time else null end,remark=#{remark}
where id=#{cartId}

update family_wallet_migration_batches set phase='VERIFY',status='VERIFIED',source_available_total=#{sourceAvailable},
  source_frozen_total=#{sourceFrozen},target_available_total=#{targetAvailable},target_frozen_total=#{targetFrozen}
where id=#{batchId} and drain_epoch=#{epoch}
